/* From Uiverse.io by KSAplay - Tags: button */
.__UIV_SCOPE__ button {
  background-color: #0050ec;
  color: white;
  font-size: 16px;
  font-weight: bold;
  padding: 15px 20px;
  border-radius: 2em;
  cursor: pointer;
  transition: 0.1s ease;
  border-width: 0;
  box-shadow: 1px 5px 0 0 #0e285d;
}

.__UIV_SCOPE__ button:hover {
  transform: translateY(-4px);
  box-shadow: 1px 9px 0 0 #0e285d;
}

.__UIV_SCOPE__ button:active {
  transform: translateY(4px);
  box-shadow: 0px 0px 0 0 #0e285d;
}
